 import React, { useState } from 'react'
import { useSlip } from '../contexts/SlipContext'
import { ShoppingBag, X, ChevronUp, ChevronDown, Send, Trash2 } from 'lucide-react'
import { Link } from 'react-router-dom'

export default function SlipButton() {
    const { slip, isOpen, setIsOpen, totalOdds, removeFromSlip, clearSlip, getSlipCount } = useSlip()
    const [showShareOptions, setShowShareOptions] = useState(false)
    const count = getSlipCount()

    if (count === 0) return null

    const getOutcomeColor = (outcome) => {
        switch(outcome) {
            case 'Home Win': return 'text-green-600'
            case 'Away Win': return 'text-blue-600'
            case 'Draw': return 'text-yellow-600'
            default: return 'text-gray-600'
        }
    }

    const getOutcomeEmoji = (outcome) => {
        switch(outcome) {
            case 'Home Win': return '🏠'
            case 'Away Win': return '✈️'
            case 'Draw': return '🤝'
            default: return '📊'
        }
    }

    return (
        <div className="fixed bottom-24 right-4 z-50 flex flex-col items-end">
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="bg-yellow-500 text-black p-4 rounded-full shadow-xl hover:bg-yellow-400 transition transform hover:scale-105 flex items-center gap-2 relative slip-button"
            >
                <ShoppingBag size={24} />
                <span className="font-bold">{count}</span>
                {count > 0 && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center animate-pulse">
                        {count}
                    </span>
                )}
            </button>

            {isOpen && (
                <div className="absolute bottom-16 right-0 w-80 bg-white rounded-xl shadow-2xl border border-gray-200 max-h-[70vh] overflow-hidden slip-popup">
                    <div className="bg-yellow-500 text-black p-3 font-bold flex justify-between items-center">
                        <span>Bet Slip ({count})</span>
                        <button onClick={() => setIsOpen(false)} className="hover:opacity-70">
                            <X size={18} />
                        </button>
                    </div>

                    <div className="p-3 max-h-[50vh] overflow-y-auto">
                        {slip.map((item, index) => (
                            <div key={index} className="border-b border-gray-100 py-2">
                                <div className="flex justify-between items-start">
                                    <div className="flex-1">
                                        <div className="text-sm font-semibold">
                                            {item.homeTeam} vs {item.awayTeam}
                                        </div>
                                        <div className={`text-xs font-medium ${getOutcomeColor(item.outcome)} flex items-center gap-1`}>
                                            {getOutcomeEmoji(item.outcome)} {item.outcome}
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => removeFromSlip(item.matchId)}
                                        className="text-gray-400 hover:text-red-500 text-xs"
                                    >
                                        <X size={14} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="border-t border-gray-200 p-3 bg-gray-50">
                        <div className="flex justify-between text-sm font-semibold mb-2">
                            <span>Total Odds</span>
                            <span className="text-yellow-600">{totalOdds.toFixed(2)}</span>
                        </div>
                        <div className="flex gap-2">
                            <button 
                                onClick={clearSlip}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg text-sm hover:bg-gray-300 transition flex items-center justify-center gap-1"
                            >
                                <Trash2 size={14} /> Clear
                            </button>
                            <button 
                                onClick={() => setShowShareOptions(!showShareOptions)}
                                className="flex-1 bg-yellow-500 text-black py-2 rounded-lg text-sm hover:bg-yellow-400 transition flex items-center justify-center gap-1"
                            >
                                <Send size={14} /> Share
                            </button>
                        </div>

                        {showShareOptions && (
                            <div className="mt-2 flex gap-2">
                                <Link 
                                    to="/feed"
                                    className="flex-1 bg-green-600 text-white py-2 rounded-lg text-sm hover:bg-green-700 transition text-center"
                                    onClick={() => {
                                        localStorage.setItem('predictfc_share_slip', JSON.stringify(slip))
                                        setIsOpen(false)
                                    }}
                                >
                                    🌍 Feed
                                </Link>
                                <Link 
                                    to="/community"
                                    className="flex-1 bg-purple-600 text-white py-2 rounded-lg text-sm hover:bg-purple-700 transition text-center"
                                    onClick={() => {
                                        localStorage.setItem('predictfc_share_slip', JSON.stringify(slip))
                                        setIsOpen(false)
                                    }}
                                >
                                    🏛️ Community
                                </Link>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    )
}
